            const dt2 = Math.min(0.033, Math.max(0.001, dt));

            // equation-hover modes (set by the page): 1 = δ_m(r') highlights density nodes, 2 = v_p(r) pulses the flow
            const mode = (hp && hp.mode) || 0;
