                const x1 = x * R.cy + z * R.sy, z1 = -x * R.sy + z * R.cy, y2 = y * R.cp - z1 * R.sp, z2 = y * R.sp + z1 * R.cp;
                pos[i3] = ox + x1; pos[i3 + 1] = oy + y2; pos[i3 + 2] = oz + z2;
